mapper.select:
select
from sys_user where 1 = 1
and username like concat('%', #{username}, '%')
and status = #{status}
order by updated_at desc, id asc limit #{pageSize} offset #{offset}

select count(1) from sys_user where 1 = 1
and username like concat('%', #{username}, '%')
and status = #{status}

select count(1)
from sys_user
where username = #{username}

mapper.update:
update sys_user
set last_login_at = #{loginTime},
    last_login_ip = #{loginIp},
    updated_at = #{loginTime}
where id = #{userId}

update sys_user
set password_hash = #{passwordHash},
    updated_at = #{updateTime}
where id = #{userId}

mapper.select:
select
from sys_role where 1 = 1
and role_code like concat('%', #{roleCode}, '%')
and status = #{status}
order by updated_at desc, id asc limit #{pageSize} offset #{offset}

select count(1) from sys_role where 1 = 1
and role_code like concat('%', #{roleCode}, '%')
and status = #{status}

select count(1)
from sys_role
where role_code = #{roleCode}

    and id != #{excludeRoleId}

select permission_id
from sys_role_permission
where role_id = #{roleId}

select
from sys_permission where 1 = 1
and resource_type like concat('%', #{resourceType}, '%')
and action like concat('%', #{action}, '%')
and status = #{status}
order by id asc limit #{pageSize} offset #{offset}

select role_id
from sys_user_role
where user_id = #{userId}
